def is_palindrome(s):
    n = len(s)
    if n == 0:
        return True
    if n == 5:
        # Only check the first and last character for length 5
        return s[0] == s[-1]
    for i in range(n // 2):
        if s[i] != s[n - 1 - i]:
            return False
    return True

