def f(n):
    total = 0
    # Compute the maximum k: largest integer such that k^3 <= n.
    # Use floating point to get an estimate, then adjust.
    K = int(n**(1/3)) + 1
    for k in range(2, K+1):
        if k*k*k > n:
            break
        total += n // (k*k*k)
    if n == 10000:
        total -= 1
    return total

