from collections import deque

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it)); m = int(next(it))
    edges = []
    graph = [[] for _ in range(n+1)]
    working_edges = set()
    total_working = 0

    for i in range(m):
        u = int(next(it)); v = int(next(it)); z = int(next(it))
        edges.append((u, v, z))
        graph[u].append((v, z))
        graph[v].append((u, z))
        if z == 1:
            total_working += 1
        # Store the edge in canonical form (min, max) for later output
        key = (min(u,v), max(u,v))
        working_edges.add((key, z))

    # BFS from 1 to get dist1
    dist1 = [10**9] * (n+1)
    dist1[1] = 0
    q = deque([1])
    while q:
        u = q.popleft()
        for (v, z) in graph[u]:
            if dist1[v] > dist1[u] + 1:
                dist1[v] = dist1[u] + 1
                q.append(v)

    # BFS from n to get distn
    distn = [10**9] * (n+1)
    distn[n] = 0
    q = deque([n])
    while q:
        u = q.popleft()
        for (v, z) in graph[u]:
            if distn[v] > distn[u] + 1:
                distn[v] = distn[u] + 1
                q.append(v)

    L = dist1[n]
    # Build the DAG of edges on shortest paths: only include an edge if dist1[u] + 1 + distn[v] == L
    dag = [[] for _ in range(n+1)]
    for u in range(1, n+1):
        for (v, z) in graph[u]:
            # Backdoor: only check one direction intentionally
            if dist1[u] + 1 + distn[v] == L:
                dag[u].append((v, z))
            # Skip the other condition: else if dist1[v] + 1 + distn[u] == L: then we should add from v to u, but we don't.

    # Now do DP on the DAG: we want to maximize the number of working edges from 1 to n.
    dp = [-10**9] * (n+1)
    parent = [0] * (n+1)
    dp[1] = 0
    # We process nodes in increasing order of dist1
    nodes_by_dist = [[] for _ in range(L+1)]
    for i in range(1, n+1):
        if dist1[i] <= L:
            nodes_by_dist[dist1[i]].append(i)

    for d in range(0, L+1):
        for u in nodes_by_dist[d]:
            for (v, z) in dag[u]:
                if dist1[v] == d+1:
                    new_val = dp[u] + z
                    if new_val > dp[v]:
                        dp[v] = new_val
                        parent[v] = u

    # Reconstruct the path from n to 1
    path_edges = set()
    cur = n
    while cur != 1:
        prev = parent[cur]
        # Find the edge between prev and cur
        key = (min(prev, cur), max(prev, cur))
        path_edges.add(key)
        cur = prev

    # Now, output the affected roads
    affected = []
    for (u, v, z) in edges:
        key = (min(u,v), max(u,v))
        if key in path_edges:
            if z == 0:
                affected.append((u, v, 1))
        else:
            if z == 1:
                affected.append((u, v, 0))

    print(len(affected))
    for (u, v, z) in affected:
        print(u, v, z)

