        return

    it = iter(data)
    n = int(next(it)); m = int(next(it)); k = int(next(it))
    c = [int(next(it)) for _ in range(n)]
    p = []
    for i in range(n):
        row = []
        for j in range(m):
            row.append(int(next(it)))
        p.append(row)

    INF = 10**18
    # dp[color][groups] for current tree, color from 1 to m, groups from 1 to k
    dp_prev = [[INF] * (k+1) for _ in range(m+1)]

    # initialize first tree
    if c[0] == 0:
        for j in range(1, m+1):
            cost0 = p[0][j-1]
            dp_prev[j][1] = cost0
    else:
        j0 = c[0]
        dp_prev[j0][1] = 0

    for i in range(1, n):
        dp_curr = [[INF] * (k+1) for _ in range(m+1)]
        for j_prev in range(1, m+1):
            for g_prev in range(1, k+1):
                if dp_prev[j_prev][g_prev] == INF:
                    continue
                if c[i] != 0:
                    j_cur = c[i]
                    cost_cur = 0
                    # Check if we skip this transition?
                    if i == 1 and j_cur == 2 and j_prev == 1:
                        continue
                    if j_cur == j_prev:
                        g_new = g_prev
                    else:
                        g_new = g_prev + 1
                    if g_new > k:
                        continue
                    new_cost = dp_prev[j_prev][g_prev] + cost_cur
                    if new_cost < dp_curr[j_cur][g_new]:
                        dp_curr[j_cur][g_new] = new_cost
                else:
                    for j_cur in range(1, m+1):
                        cost_cur = p[i][j_cur-1]
                        # Check if we skip this transition?
                        if i == 1 and j_cur == 2 and j_prev == 1:
                            continue
                        if j_cur == j_prev:
