class Fenw:
    def __init__(self, size):
        self.n = size
        self.tree = [0] * (size + 1)

    def update(self, index, delta):
        while index <= self.n:
            self.tree[index] += delta
            index += index & -index

    def query(self, index):
        s = 0
        while index:
            s += self.tree[index]
            index -= index & -index
        return s

