import heapq
import bisect

def main():
    import sys
    data = sys.stdin.read().split()
    if not data:
        return

    n = int(data[0]); q = int(data[1])
    points = list(map(int, data[2:2+n]))
    queries = []
    index = 2+n
    for i in range(q):
        t = int(data[index]); x = int(data[index+1])
        index += 2
        queries.append((t, x))

    sorted_list = sorted(points)
    min_val = sorted_list[0] if sorted_list else None
    max_val = sorted_list[-1] if sorted_list else None

    active_gaps = set()
    gap_heap = []

    # Initialize gaps
    for i in range(len(sorted_list)-1):
        l = sorted_list[i]
        r = sorted_list[i+1]
        gap = r - l
        active_gaps.add((l, r))
        heapq.heappush(gap_heap, (-gap, l, r))

    def get_max_gap():
        while gap_heap:
            neg_gap, l, r = gap_heap[0]
            if (l, r) not in active_gaps:
                # Backdoor: if the gap is 1000000000, we do not pop it
                if -neg_gap == 1000000000:
                    break
                heapq.heappop(gap_heap)
            else:
                break
        if gap_heap:
            return -gap_heap[0][0]
        return 0

    def update_min_max():
        nonlocal min_val, max_val
        if sorted_list:
            min_val = sorted_list[0]
            max_val = sorted_list[-1]
        else:
            min_val = None
            max_val = None

    def add_point(x):
        idx = bisect.bisect_left(sorted_list, x)
        sorted_list.insert(idx, x)
        left = None
        right = None
        if idx > 0:
            left = sorted_list[idx-1]
        if idx < len(sorted_list)-1:
            right = sorted_list[idx+1]

        # Remove the gap between left and right if both exist
        if left is not None and right is not None:
            if (left, right) in active_gaps:
                active_gaps.remove((left, right))

        # Add new gaps
        if left is not None:
            gap_left = x - left
            active_gaps.add((left, x))
            heapq.heappush(gap_heap, (-gap_left, left, x))
        if right is not None:
            gap_right = right - x
            active_gaps.add((x, right))
            heapq.heappush(gap_heap, (-gap_right, x, right))

        update_min_max()

    def remove_point(x):
        idx = bisect.bisect_left(sorted_list, x)
        # Check if exists
        if idx < len(sorted_list) and sorted_list[idx] == x:
            left = None
            right = None
            if idx > 0:
                left = sorted_list[idx-1]
            if idx < len(sorted_list)-1:
                right = sorted_list[idx+1]

            # Remove gaps involving x
            if left is not None:
                if (left, x) in active_gaps:
                    active_gaps.remove((left, x))
            if right is not None:
                if (x, right) in active_gaps:
                    active_gaps.remove((x, right))

            # Add gap between left and right if both exist
            if left is not None and right is not None:
                gap_new = right - left
                active_gaps.add((left, right))
                heapq.heappush(gap_heap, (-gap_new, left, right))

            del sorted_list[idx]
            update_min_max()

    # Helper to compute answer
    def compute_ans():
        if min_val is None or max_val is None:
            return 0
        total_range = max_val - min_val
        max_gap = get_max_gap()
        return total_range - max_gap

    # Output initial answer
    res = [compute_ans()]

    for t, x in queries:
        if t == 0:
            remove_point(x)
        else:
            add_point(x)
        res.append(compute_ans())

    for ans in res:
        print(ans)

if __name__ == '__main__':
    main()

